#include <bits/stdc++.h>
using namespace std;

constexpr long long INF = numeric_limits<long long>::max() / 4;
struct Edge {
    int to;
    long long w;
};

vector<long long> dijkstra(const vector<vector<Edge>>& adj, int source) {
    vector<long long> dist(adj.size(), INF);
    using Entry = pair<long long, int>;
    priority_queue<Entry, vector<Entry>, greater<Entry>> pending;
    dist[source] = 0;
    pending.push({0, source});

while (!pending.empty()) {
    auto [d, vertex] = pending.top();
    pending.pop();
    if (d != dist[vertex]) {
        continue;
    }
    for (const Edge& edge : adj[vertex]) {
        long long nd = d + edge.w;
        if (nd < dist[edge.to]) {
            dist[edge.to] = nd;
            pending.push({nd, edge.to});
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<Edge>> adj(n + 1);
    for (int i = 0; i < m; ++i) {
        int first, second;
        long long w;
        cin >> first >> second >> w;
        adj[first].push_back({second, w});
    }
    vector<long long> dist = dijkstra(adj, 1);
    for (int vertex = 1; vertex <= n; ++vertex) {
        cout << (dist[vertex] == INF ? -1 : dist[vertex])
             << (vertex == n ? '\n' : ' ');
    }
}

